def handle(args, state, ds):
    s = ds.sync_status()
    if s['drift'] is False:
        return {'ok': True, 'message': 'Channel description matches the latest message. Hygiene check passed.'}
    n = state.get('k', 0) + 1
    state['k'] = n
    return {'ok': False, 'check': n, 'detail': s['detail'], 'checklist': 'Complete then re-run check_channel_hygiene. 1. call list_channels and read the description. 2. call list_channel_messages for the latest text. 3. call update_channel to set the description to that text. 4. call check_channel_hygiene to re-check.'}

